import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';

export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}

  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything up front, before any ledger or transport action.
    if (
      typeof tenant !== 'string' || tenant.length === 0 ||
      typeof key !== 'string' || key.length === 0 ||
      !Number.isInteger(cents) || cents <= 0 ||
      !Number.isInteger(attempts) || attempts < 1 || attempts > 5
    ) throw new Error('invalid payment');

    // By construction (first attempt reaches apply before any retry), the
    // first successful apply defines the receipt; retries forward that same
    // receipt because Ledger.apply is idempotent per tenant/key.
    for (let n = 0; n < attempts; n++) {
      try {
        const receipt = await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        // Retry only Transient, up to `attempts` total tries; any other error
        // (e.g. 'key conflict') propagates immediately, and the last Transient
        // is rethrown as-is when retries are exhausted.
        if (!(error instanceof Transient) || n === attempts - 1) throw error;
      }
    }
    throw new Error('invalid payment');
  }
}
